(() => {
  const icons = {
    grid: '<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
    activity: '<path d="M3 12h4l3-8 4 16 3-8h4"/>',
    send: '<path d="M22 2 11 13"/><path d="m22 2-7 20-4-9-9-4Z"/>',
    receive: '<path d="M12 3v12"/><path d="m7 10 5 5 5-5"/><path d="M5 19h14"/>',
    coins: '<circle cx="8" cy="8" r="5"/><path d="M20 8h-3M8 3v10M16 13a5 5 0 1 0 5 5"/><path d="M16 14v8M12 18h8"/>',
    user: '<path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/>',
    bell: '<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/>',
    eye: '<path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/>',
    eyeOff: '<path d="m3 3 18 18M10.6 10.6a2 2 0 0 0 2.8 2.8"/><path d="M9.9 5.2A10.7 10.7 0 0 1 12 5c6.5 0 10 7 10 7a13.8 13.8 0 0 1-3 3.7M6.2 6.2C3.5 8 2 12 2 12s3.5 7 10 7a10.8 10.8 0 0 0 3-.4"/>',
    arrow: '<path d="M5 12h14M13 6l6 6-6 6"/>',
    chevron: '<path d="m9 18 6-6-6-6"/>',
    back: '<path d="m15 18-6-6 6-6"/>',
    copy: '<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',
    check: '<path d="m5 12 4 4L19 6"/>',
    shield: '<path d="M12 22s8-4 8-11V5l-8-3-8 3v6c0 7 8 11 8 11Z"/><path d="m9 12 2 2 4-4"/>',
    lock: '<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 1 1 8 0v3"/>',
    settings: '<path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z"/><path d="m19.4 15 .1.1 1.4 1.1-1.4 2.4-1.7-.7a8 8 0 0 1-1.7 1l-.3 1.8h-2.8l-.3-1.8a8 8 0 0 1-1.7-1l-1.7.7-1.4-2.4 1.4-1.1a8 8 0 0 1 0-2l-1.4-1.1 1.4-2.4 1.7.7a8 8 0 0 1 1.7-1l.3-1.8h2.8l.3 1.8a8 8 0 0 1 1.7 1l1.7-.7 1.4 2.4-1.4 1.1a8 8 0 0 1 0 2Z"/>',
    link: '<path d="M10 13a5 5 0 0 0 7.1 0l3-3A5 5 0 0 0 13 2.9l-1.7 1.7"/><path d="M14 11a5 5 0 0 0-7.1 0l-3 3A5 5 0 0 0 11 21.1l1.7-1.7"/>',
    warning: '<path d="m10.3 3.9-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3.1l-8-14a2 2 0 0 0-3.4 0Z"/><path d="M12 9v4M12 17h.01"/>',
    logout: '<path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><path d="m16 17 5-5-5-5M21 12H9"/>',
    clock: '<circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/>',
    globe: '<circle cx="12" cy="12" r="10"/><path d="M2 12h20M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10Z"/>',
    up: '<path d="m7 14 5-5 5 5"/>',
    down: '<path d="m7 10 5 5 5-5"/>',
    search: '<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',
    x: '<path d="m18 6-12 12M6 6l12 12"/>',
    external: '<path d="M15 3h6v6M10 14 21 3"/><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/>',
  };
  const icon = (name, size = 18) => `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name] || icons.grid}</svg>`;
  const seedAssets = [
    { id: 'eth', name: 'Ethereum', ticker: 'ETH', symbol: 'Ξ', kind: 'eth', amount: 2.4581, price: 3240.5, change: '+2.84%', network: 'Sepolia' },
    { id: 'nc', name: 'Nuur Coin', ticker: 'NC', symbol: 'N', kind: 'nc', amount: 12500, price: .084, change: '+5.12%', network: 'Sepolia' },
    { id: 'usdc', name: 'USD Coin', ticker: 'USDC', symbol: '$', kind: 'usdc', amount: 850.25, price: 1, change: '+0.01%', network: 'Sepolia' },
  ];
  let assets = seedAssets.map(asset => ({ ...asset }));
  const initialTransactions = [
    { id: '0x8f3a…c210', kind: 'received', asset: 'eth', amount: .42, date: 'Today, 10:42 AM', status: 'Confirmed', hash: '0x8f3a2c961b804c31d1750ca8a6617d82e1408a624eed16b095e4c943c210', address: '0x71C7...8A3f', demo: true },
    { id: '0xb72c…a91d', kind: 'sent', asset: 'usdc', amount: 85, date: 'Yesterday, 4:18 PM', status: 'Confirmed', hash: '0xb72c88a72f548934991dbba4d8128f3f84239a1ae5a7e01c7611bf91a91d', address: '0x9A1c...eB42', demo: true },
    { id: '0x3e91…f05b', kind: 'received', asset: 'nc', amount: 2400, date: 'Oct 28, 2:05 PM', status: 'Confirmed', hash: '0x3e913f800b2f1b295f549a4112549de0ac36478d4eb99f1c05b', address: '0xC2d4...B71e', demo: true },
    { id: '0xc4d2…991f', kind: 'sent', asset: 'eth', amount: .15, date: 'Oct 24, 9:30 AM', status: 'Confirmed', hash: '0xc4d2ad27ee8a3f50cf416887cf93826d06c21f049c39297f13991f', address: '0x5520...f038', demo: true },
  ];
  const networks = ['Sepolia', 'Base Sepolia', 'Polygon Amoy'];
  const state = {
    page: 'home', onboarding: 'welcome', ready: false, network: 'Sepolia', hideBalance: false,
    asset: 'eth', historyFilter: 'All', historyNetwork: 'All networks', setting: 'Profile',
    sendStep: 0, sendData: { recipient: '', amount: '' }, receiveAsset: 'eth', transaction: null,
    transactions: initialTransactions.slice(), security: { biometric: true, lock: true, analytics: false, offline: false },
    currency: 'USD', lockTime: '5 minutes', toastTimer: null,
  };
  const assetById = id => assets.find(a => a.id === id);
  const totalBalance = () => assets.reduce((total, asset) => total + asset.amount * asset.price, 0);
  const money = (value, decimals = 2) => state.hideBalance ? '••••••' : new Intl.NumberFormat('en-US', { style: 'currency', currency: state.currency, minimumFractionDigits: decimals, maximumFractionDigits: decimals }).format(Number(value));
  const quantity = (value, ticker) => state.hideBalance ? `•••• ${ticker}` : `${Number(value).toLocaleString('en-US', { maximumFractionDigits: 4 })} ${ticker}`;
  const displayValue = (asset, amount = asset.amount) => money(asset.price * amount);
  const demoAddress = '0x71C7656EC7ab88b098defB751B7401B5f6d8976F';
  const nav = [
    ['home', 'Home', 'grid'], ['activity', 'Activity', 'activity'], ['send', 'Send', 'send'], ['receive', 'Receive', 'receive'], ['assets', 'Assets', 'coins'], ['settings', 'Profile', 'user'],
  ];
  const viewHeader = title => ({ home: 'Home', activity: 'Activity', send: 'Send', receive: 'Receive', assets: 'Assets', assetDetail: 'Asset details', portfolio: 'Portfolio', network: 'Network', settings: state.setting, transactionDetail: 'Transaction details' }[title] || title);

  function render() {
    const app = document.getElementById('app');
    if (!state.ready) { app.innerHTML = renderOnboarding(); bind(); return; }
    app.innerHTML = `<div class="app-shell"><aside class="sidebar">${renderBrand()}<div class="nav-label">Wallet</div><nav class="nav-list" aria-label="Main navigation">${nav.map(([id, label, glyph]) => navItem(id,label,glyph)).join('')}</nav><div class="sidebar-spacer"></div><div class="network-card"><div class="network-card-top"><span>Network</span><span class="network-live"><i class="live-dot"></i> Testnet</span></div><select class="network-select" data-action="network-change" aria-label="Select network">${networks.map(n => `<option ${state.network===n?'selected':''}>${n}</option>`).join('')}</select></div><div class="side-profile" data-action="goto" data-page="settings" role="button" tabindex="0"><div class="avatar">NA</div><div><div class="profile-name">Nuur Account</div><div class="profile-wallet">Wallet 01 · ${shortAddress(demoAddress)}</div></div><span class="more-icon">${icon('chevron',14)}</span></div></aside><main class="main-area"><header class="topbar"><div class="crumb"><span>NUUR WALLET</span>${icon('chevron',12)}<span class="crumb-current">${viewHeader(state.page)}</span></div><div class="mobile-brand">${renderBrand(true)}</div><div class="topbar-right"><span class="testnet-pill"><i class="live-dot"></i> ${state.network}</span><button class="icon-button" aria-label="Notifications" data-action="notify" title="Notifications">${icon('bell')}</button><button class="icon-button topbar-profile" aria-label="Profile" data-action="goto" data-page="settings">${icon('user')}</button></div></header><section class="content">${state.security.offline?`<div class="offline-banner">${icon('warning',14)} You’re offline. Cached sample balances remain visible; transaction actions are unavailable.</div>`:''}${renderPage()}</section></main>${renderMobileNav()}</div><div id="toast-root"></div>`;
    bind();
  }

  function renderBrand(mobile = false) {
    return `<div class="${mobile ? 'mobile-brand-inner' : 'brand'}"><div class="brand-mark">N</div><div><div class="brand-name">NUUR</div>${mobile ? '' : '<div class="brand-caption">Digital wallet</div>'}</div></div>`;
  }
  function navItem(id,label,glyph) { return `<button class="nav-item ${state.page===id || (id==='assets' && state.page==='assetDetail') || (id==='activity' && state.page==='transactionDetail') || (id==='settings' && state.page==='settings')?'active':''}" data-action="goto" data-page="${id}">${icon(glyph)}<span>${label}</span>${id==='activity'?`<span class="nav-count">${state.transactions.length}</span>`:''}</button>`; }
  function renderMobileNav() { return `<nav class="mobile-nav" aria-label="Mobile navigation">${nav.map(([id,label,glyph])=>`<button class="${state.page===id?'active':''} ${id==='send'||id==='receive'?'strong':''}" data-action="goto" data-page="${id}" aria-label="${label}">${icon(glyph)}<span>${label}</span></button>`).join('')}</nav>`; }
  function renderOnboarding() {
    const step = state.onboarding;
    const intro = step === 'welcome';
    const titles = { create: 'Create your demo account', security: 'Security starts with you', backup: 'Keep your account protected', confirm: 'Ready for your demo wallet?', import: 'Recover an account', importInfo: 'Account recovery stays protected' };
    let panel = '';
    if (intro) panel = `<h2>Welcome to NUUR</h2><p>A calm, clear place to explore digital assets. This interactive prototype uses sample data and never connects to a blockchain.</p><button class="onboard-option" data-action="onboard" data-step="create"><span class="action-icon">${icon('coins')}</span><span><strong>Create an account</strong><small>Set up a new demo account</small></span>${icon('chevron')}</button><button class="onboard-option" data-action="onboard" data-step="import"><span class="action-icon">${icon('receive')}</span><span><strong>Recover an account</strong><small>Explore the account recovery flow</small></span>${icon('chevron')}</button><button class="primary-button" style="width:100%;margin-top:9px" data-action="enter-demo">Explore demo wallet ${icon('arrow',15)}</button><div class="onboard-note">${icon('warning')} <span>Prototype only. No custody provider is connected, and all balances are simulated.</span></div>`;
    if (step === 'create') panel = `<h2>${titles.create}</h2><p>NUUR's planned model uses a professional third-party custody provider. This prototype skips identity checks and opens a sample account only.</p><div class="onboard-note">${icon('lock')} <span>No provider credentials, signing secrets, or customer account data are used by this demo.</span></div><div class="onboard-actions"><button class="primary-button" data-action="onboard" data-step="security">Continue ${icon('arrow',15)}</button><button class="secondary-button" data-action="onboard" data-step="welcome">Back</button></div>`;
    if (step === 'security') panel = `<h2>${titles.security}</h2><p>Customer access and custody signing are separate responsibilities. A production wallet will use the approved provider's security controls, explicit transaction policies, and auditable approvals.</p><div class="data-row"><span>Custody model</span><strong>Third-party provider</strong></div><div class="data-row"><span>Network activity</span><strong>Test networks only</strong></div><div class="data-row"><span>Withdrawals</span><strong>Policy and review controls</strong></div><div class="onboard-actions"><button class="primary-button" data-action="onboard" data-step="backup">I understand ${icon('arrow',15)}</button><button class="secondary-button" data-action="onboard" data-step="create">Back</button></div>`;
    if (step === 'backup') panel = `<h2>${titles.backup}</h2><p>For a custodial account, recovery follows a verified account-recovery process. NUUR support should never ask for your password, one-time code, or authentication approval.</p><div class="onboard-note">${icon('shield')} <span>This demo does not perform identity checks or recover a real account.</span></div><label class="checkbox-row"><input type="checkbox" id="backup-read" /> <span>I understand that support should never ask me to share a password or verification code.</span></label><div class="onboard-actions"><button class="primary-button" data-action="backup-next" disabled id="backup-next">Continue to confirmation ${icon('arrow',15)}</button><button class="secondary-button" data-action="onboard" data-step="security">Back</button></div>`;
    if (step === 'confirm') panel = `<h2>${titles.confirm}</h2><p>Your sample wallet is ready to explore. All balances and activity are simulated, and no funds can be sent or received.</p><div class="profile-banner surface"><div class="avatar">NA</div><div><h2>Nuur Account</h2><p>Demo wallet · ${shortAddress(demoAddress)}</p></div></div><div class="onboard-actions"><button class="primary-button" data-action="finish-onboarding">Open demo wallet ${icon('arrow',15)}</button><button class="secondary-button" data-action="onboard" data-step="backup">Back</button></div>`;
    if (step === 'import') panel = `<h2>${titles.import}</h2><p>Account recovery for a custodial wallet should verify your identity and use a documented support process. This prototype does not collect personal information.</p><div class="onboard-option" style="cursor:default"><span class="action-icon">${icon('shield')}</span><span><strong>Safe recovery walkthrough</strong><small>See the steps without submitting information</small></span></div><div class="onboard-actions"><button class="primary-button" data-action="onboard" data-step="importInfo">Continue safely ${icon('arrow',15)}</button><button class="secondary-button" data-action="onboard" data-step="welcome">Back</button></div>`;
    if (step === 'importInfo') panel = `<h2>${titles.importInfo}</h2><p>A production recovery process should verify account ownership, protect against social engineering, and notify the customer about recovery events. Here, recovery is represented by a sample account only.</p><div class="onboard-note">${icon('warning')} <span>No personal information or verification code is requested by this prototype.</span></div><div class="onboard-actions"><button class="primary-button" data-action="finish-onboarding">Open sample wallet ${icon('arrow',15)}</button><button class="secondary-button" data-action="onboard" data-step="import">Back</button></div>`;
    return `<div class="onboarding"><div class="onboarding-art"><div class="onboard-brand">${renderBrand()}</div><div class="onboard-center"><div class="onboard-kicker">A new kind of clarity</div><h1>Own your assets.<br /><span>Move with confidence.</span></h1><p>Built for everyday decisions, with security and simplicity at its core.</p></div><div class="onboard-foot">CUSTODIAL WALLET · TESTNET PROTOTYPE</div></div><div class="onboard-panel-wrap"><div class="onboard-panel">${panel}${!intro?'<button class="text-button" data-action="enter-demo">Skip to demo wallet</button>':''}</div></div></div>`;
  }

  function pageHeading(title, note, actions = '') { return `<div class="page-heading"><div><div class="eyebrow">${state.page==='home'?'YOUR WALLET':'NUUR WALLET'}</div><h1>${title}</h1>${note?`<p class="heading-note">${note}</p>`:''}</div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`; }
  function demoRibbon() { return `<div class="demo-ribbon">${icon('warning',14)} Demo environment · balances and blockchain activity are simulated</div>`; }
  function assetIcon(a, size = '') { return `<span class="coin-icon coin-${a.kind} ${size}">${a.symbol}</span>`; }
  function renderPage() {
    switch (state.page) {
      case 'home': return renderHome();
      case 'assets': return renderAssets();
      case 'assetDetail': return renderAssetDetail();
      case 'portfolio': return renderPortfolio();
      case 'activity': return renderActivity();
      case 'send': return renderSend();
      case 'receive': return renderReceive();
      case 'settings': return renderSettings();
      case 'transactionDetail': return renderTransactionDetail();
      case 'network': return renderNetwork();
      default: return renderHome();
    }
  }
  function renderHome() {
    const actions = `<button class="secondary-button" data-action="goto" data-page="portfolio">${icon('grid',14)} Portfolio</button>`;
    return `${pageHeading('Good morning, Nuur', 'Here is your portfolio at a glance.', actions)}${demoRibbon()}<div class="dashboard-grid" style="margin-top:17px"><section class="balance-card surface"><div class="balance-top"><span class="balance-label">Total portfolio value</span><button class="visibility-button" data-action="toggle-balance">${icon(state.hideBalance?'eyeOff':'eye',13)} ${state.hideBalance?'Show':'Hide'} balance</button></div><div class="total-value">${money(totalBalance())}</div><div class="change-line"><span class="change-badge">↗ 4.28%</span><span>+$286.40 this week</span></div><div class="balance-bottom"><div><div class="balance-caption">Updated just now · ${state.network}</div><div class="chart-label" style="margin-top:9px">Portfolio performance</div></div>${sparkline()}</div></section><section class="action-card surface"><div class="card-heading"><h2 class="card-title">Quick actions</h2><span class="eyebrow" style="margin:0;letter-spacing:.09em">TESTNET ONLY</span></div><div class="action-grid"><button class="action-button" data-action="goto" data-page="send"><span class="action-icon">${icon('send')}</span><span><span class="action-label">Send</span><span class="action-sub">Transfer assets</span></span></button><button class="action-button receive" data-action="goto" data-page="receive"><span class="action-icon">${icon('receive')}</span><span><span class="action-label">Receive</span><span class="action-sub">Share address</span></span></button><button class="action-button" data-action="goto" data-page="assets"><span class="action-icon">${icon('coins')}</span><span><span class="action-label">Assets</span><span class="action-sub">View holdings</span></span></button><button class="action-button" data-action="goto" data-page="activity"><span class="action-icon">${icon('activity')}</span><span><span class="action-label">Activity</span><span class="action-sub">Track transactions</span></span></button></div></section></div><div class="lower-grid"><section class="panel surface"><div class="card-heading"><h2 class="card-title">Your assets</h2><button class="card-link" data-action="goto" data-page="assets">View all ${icon('arrow',12)}</button></div><div class="asset-list">${assets.map(assetRow).join('')}</div></section><section class="panel surface"><div class="card-heading"><h2 class="card-title">Recent activity</h2><button class="card-link" data-action="goto" data-page="activity">See all ${icon('arrow',12)}</button></div><div class="activity-list">${state.transactions.slice(0,3).map(activityRow).join('')}</div></section></div>`;
  }
  function sparkline() { return `<svg class="sparkline" viewBox="0 0 235 44" fill="none" aria-label="Portfolio trend chart"><defs><linearGradient id="spark-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#efcb64" stop-opacity=".25"/><stop offset="1" stop-color="#efcb64" stop-opacity="0"/></linearGradient></defs><path d="M0 34 18 30 35 32 54 22 73 25 91 18 110 23 129 10 147 14 166 8 184 12 204 4 235 8V44H0Z" fill="url(#spark-fill)"/><path d="M0 34 18 30 35 32 54 22 73 25 91 18 110 23 129 10 147 14 166 8 184 12 204 4 235 8" stroke="#efcb64" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>`; }
  function assetRow(a) { return `<button class="asset-row" data-action="asset-detail" data-asset="${a.id}"><span class="asset-info">${assetIcon(a)}<span><span class="asset-name">${a.name}</span><span class="asset-ticker">${a.ticker} · ${state.network}</span></span></span><span class="asset-amount">${quantity(a.amount,a.ticker)}<span>${money(a.price)}</span></span><span class="asset-value">${displayValue(a)}<span>${a.change} · 24h</span></span></button>`; }
  function activityRow(tx) {
    const a = assetById(tx.asset), sent = tx.kind === 'sent';
    return `<button class="activity-row" data-action="transaction-detail" data-tx="${tx.id}" style="width:100%;border-left:0;border-right:0;border-bottom:0;color:inherit;background:transparent;text-align:left;cursor:pointer"><span class="activity-symbol ${sent?'sent':''}">${icon(sent?'send':'receive',15)}</span><span class="activity-copy"><span class="activity-name">${sent?'Sent':'Received'} ${a.ticker}</span><span class="activity-meta">${tx.date} <span>·</span> <span class="status ${tx.status==='Pending'?'pending':''}"><i class="status-dot"></i>${tx.status}</span></span></span><span class="activity-amount ${sent?'out':'in'}">${sent?'−':'+'}${quantity(tx.amount,a.ticker)}<small>${money(tx.amount*a.price)}</small></span></button>`;
  }
  function renderAssets() { return `${pageHeading('Assets', 'Your digital assets on supported test networks.', `<button class="secondary-button" data-action="goto" data-page="network">${icon('globe',14)} ${state.network}</button>`)}${demoRibbon()}<div class="panel surface" style="margin-top:17px"><div class="card-heading"><h2 class="card-title">All assets <span class="inline-demo">${assets.length} assets</span></h2><button class="card-link" data-action="goto" data-page="portfolio">Portfolio view ${icon('arrow',12)}</button></div><div class="asset-list">${assets.map(assetRow).join('')}</div></div><div class="warning-box" style="max-width:680px;margin-top:14px">${icon('warning')} Demo balances are illustrative only and do not represent real or transferable funds.</div>`; }
  function renderAssetDetail() {
    const a = assetById(state.asset) || assets[0];
    return `<button class="back-button" data-action="goto" data-page="assets">${icon('back',14)} Back to assets</button>${demoRibbon()}<div class="detail-grid" style="margin-top:15px"><section class="detail-price surface"><div class="asset-detail-top">${assetIcon(a)}<span><h2>${a.name}</h2><span class="asset-ticker">${a.ticker} · ${state.network}</span></span></div><div class="detail-total">${displayValue(a)}</div><div class="change-line"><span class="change-badge">↗ ${a.change}</span><span>Past 24 hours</span></div><div class="range-row">${['1D','1W','1M','1Y','ALL'].map((r,i)=>`<button class="range-button ${i===1?'active':''}" data-action="range" data-range="${r}">${r}</button>`).join('')}</div><svg class="large-chart" viewBox="0 0 620 185" preserveAspectRatio="none"><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#efcb64" stop-opacity=".22"/><stop offset="1" stop-color="#efcb64" stop-opacity="0"/></linearGradient></defs><path d="M0 150C30 130 44 139 70 119S115 135 142 102s38 12 67-12 38 18 70-8 46 3 76-25 48 33 79-11 50 14 82-5 56 10 104-25v169H0Z" fill="url(#chartFill)"/><path d="M0 150C30 130 44 139 70 119S115 135 142 102s38 12 67-12 38 18 70-8 46 3 76-25 48 33 79-11 50 14 82-5 56 10 104-25" fill="none" stroke="#efcb64" stroke-width="2.5" vector-effect="non-scaling-stroke"/></svg></section><section class="panel surface"><div class="card-heading"><h2 class="card-title">Your balance</h2></div><div class="data-row"><span>Available</span><strong>${quantity(a.amount,a.ticker)}</strong></div><div class="data-row"><span>Price</span><strong>${money(a.price)}</strong></div><div class="data-row"><span>Network</span><strong>${state.network} <span class="status pending" style="margin-left:4px">Testnet</span></strong></div><div class="data-row"><span>Contract</span><strong>${a.id==='nc'?'Demo token':'Test network asset'}</strong></div><div class="button-row"><button class="primary-button" data-action="goto" data-page="send">${icon('send',14)} Send</button><button class="secondary-button" data-action="receive-asset" data-asset="${a.id}">${icon('receive',14)} Receive</button></div></section></div><section class="panel surface" style="margin-top:18px"><div class="card-heading"><h2 class="card-title">Recent ${a.ticker} activity</h2><button class="card-link" data-action="goto" data-page="activity">View all</button></div><div class="activity-list">${state.transactions.filter(tx=>tx.asset===a.id).map(activityRow).join('')||'<div class="empty-hint">No activity for this asset yet.</div>'}</div></section>`;
  }
  function renderPortfolio() {
    return `${pageHeading('Portfolio', 'A clear view of your simulated holdings.', `<button class="secondary-button" data-action="toggle-balance">${icon(state.hideBalance?'eyeOff':'eye',14)} ${state.hideBalance?'Show':'Hide'} values</button>`)}${demoRibbon()}<div class="portfolio-stats" style="margin-top:17px"><div class="stat-card surface"><div class="stat-label">Total balance</div><div class="stat-value">${money(totalBalance())}</div><div class="stat-change">↗ 4.28% this week</div></div><div class="stat-card surface"><div class="stat-label">Assets held</div><div class="stat-value">${assets.length}</div><div class="stat-change" style="color:var(--muted)">Across ${networks.length} test networks</div></div><div class="stat-card surface"><div class="stat-label">Largest holding</div><div class="stat-value">Ethereum</div><div class="stat-change" style="color:var(--muted)">${money(assets[0].amount*assets[0].price)} · ETH</div></div></div><div class="detail-grid"><section class="panel surface"><div class="card-heading"><h2 class="card-title">Asset allocation</h2><span class="asset-ticker">Indicative demo values</span></div><div style="display:flex;align-items:center;gap:20px;padding:10px 0 5px"><div style="width:140px;height:140px;border-radius:50%;background:conic-gradient(#efcb64 0 72%,#637eaa 72% 91%,#20c997 91% 100%);display:grid;place-items:center"><div style="width:92px;height:92px;border-radius:50%;background:#1b293a;display:grid;place-items:center;color:var(--muted);font-size:10px">Allocation</div></div><div style="display:grid;gap:13px;flex:1">${assets.map(a=>`<div style="display:flex;align-items:center;gap:8px;font-size:10px"><i style="width:8px;height:8px;border-radius:50%;background:${a.kind==='nc'?'#efcb64':a.kind==='eth'?'#637eaa':'#20c997'}"></i><span style="flex:1">${a.name}</span><strong>${Math.round(a.amount*a.price/totalBalance()*100)}%</strong></div>`).join('')}</div></div></section><section class="panel surface"><div class="card-heading"><h2 class="card-title">Holdings</h2><button class="card-link" data-action="goto" data-page="assets">Manage</button></div><div class="asset-list">${assets.map(assetRow).join('')}</div></section></div>`;
  }
  function renderActivity() {
    const filtered = state.transactions.filter(tx => (state.historyFilter==='All' || (state.historyFilter==='Sent' && tx.kind==='sent') || (state.historyFilter==='Received' && tx.kind==='received') || (state.historyFilter==='Pending' && tx.status==='Pending')) && (state.historyNetwork==='All networks' || (tx.network||'Sepolia')===state.historyNetwork));
    const chips = ['All','Sent','Received','Pending'];
    return `${pageHeading('Activity', 'Review your simulated transaction history.', `<button class="secondary-button" data-action="export-history">${icon('down',14)} Export</button>`)}${demoRibbon()}<section class="panel surface" style="margin-top:17px"><div class="filter-controls"><div class="filter-row" style="margin:0">${chips.map(c=>`<button class="filter-chip ${state.historyFilter===c?'active':''}" data-action="history-filter" data-filter="${c}">${c}${c==='All'?` (${state.transactions.length})`:''}</button>`).join('')}</div><select class="compact-select" data-action="history-network" aria-label="Filter by network"><option>All networks</option>${networks.map(n=>`<option ${state.historyNetwork===n?'selected':''}>${n}</option>`).join('')}</select></div><div style="overflow-x:auto"><table class="history-table"><thead><tr><th>Transaction</th><th>Asset</th><th>Amount</th><th>Date</th><th>Status</th><th></th></tr></thead><tbody>${filtered.length?filtered.map(historyRow).join(''):'<tr><td colspan="6" class="table-empty">No transactions match this filter.</td></tr>'}</tbody></table></div></section><div class="warning-box" style="max-width:680px">${icon('warning')} History is stored in this page session only. Nothing is broadcast to a blockchain.</div>`;
  }
  function historyRow(tx) { const a=assetById(tx.asset); return `<tr data-action="transaction-detail" data-tx="${tx.id}" tabindex="0" aria-label="Open ${tx.kind} ${a.ticker} transaction from ${tx.date}"><td><span style="display:flex;align-items:center;gap:8px"><span class="activity-symbol ${tx.kind==='sent'?'sent':''}" style="width:27px;height:27px;border-radius:9px">${icon(tx.kind==='sent'?'send':'receive',12)}</span><span><strong style="color:var(--text);font-size:10px">${tx.kind==='sent'?'Sent':'Received'}</strong><small style="display:block;margin-top:3px;color:var(--subtle);font-size:8px">${shortAddress(tx.address)}</small></span></span></td><td><span class="table-asset">${assetIcon(a)}${a.ticker}</span></td><td class="amount-cell">${tx.kind==='sent'?'−':'+'}${quantity(tx.amount,a.ticker)}<small style="display:block;margin-top:3px;color:var(--subtle);font-size:8px">${money(tx.amount*a.price)}</small></td><td>${tx.date}</td><td><span class="status ${tx.status==='Pending'?'pending':''}"><i class="status-dot"></i>${tx.status}</span></td><td>${icon('chevron',13)}</td></tr>`; }
  function renderSend() {
    const step = state.sendStep;
    if (state.transaction?.mode==='loading') return renderSendLoading();
    if (state.transaction?.mode==='send') return renderSendResult();
    const selected=assetById(state.asset)||assets[0];
    const headings=['Choose an asset','Who are you sending to?','How much would you like to send?','Review your transfer'];
    const subtitles=['Select a test asset to continue.','Enter a valid public testnet address.','Enter an amount, then review the network fee.','Check the details carefully before simulating.'];
    let body='';
    if(step===0) body=`<div class="select-asset-list">${assets.map(a=>`<button class="select-asset ${state.asset===a.id?'selected':''}" data-action="select-send-asset" data-asset="${a.id}">${assetIcon(a)}<span class="asset-info"><span><span class="asset-name">${a.name}</span><span class="asset-ticker">${a.ticker} · ${state.network}</span></span></span><span class="select-asset-balance">${quantity(a.amount,a.ticker)}<br /><span style="display:inline-block;margin-top:4px;color:var(--subtle)">${displayValue(a)}</span></span>${state.asset===a.id?icon('check',15):''}</button>`).join('')}</div>`;
    if(step===1) body=`<div class="field-group"><label class="form-label" for="recipient">Recipient address</label><input class="field" id="recipient" data-input="recipient" placeholder="0x…" autocomplete="off" spellcheck="false" value="${escapeAttr(state.sendData.recipient)}"/><div class="field-hint">Paste a public wallet address on ${state.network}. Address checks happen on this device.</div><div class="field-error" id="recipient-error">Enter a valid 42-character 0x address.</div></div><div class="setting-item"><span><span class="setting-title">Network</span><span class="setting-description" style="display:block">Transactions stay on test networks</span></span><select class="compact-select" data-action="network-change">${networks.map(n=>`<option ${state.network===n?'selected':''}>${n}</option>`).join('')}</select></div>`;
    if(step===2) body=`<div class="field-group"><label class="form-label" for="amount">Amount available · ${quantity(selected.amount,selected.ticker)}</label><div class="amount-input-wrap"><input class="field" id="amount" data-input="amount" type="number" min="0" step="any" placeholder="0.00" value="${escapeAttr(state.sendData.amount)}"/><button class="max-button" data-action="max-amount">MAX</button><span class="amount-token">${selected.ticker}</span></div><div class="field-hint">Approx. value: <span id="amount-value">${state.sendData.amount?money(Number(state.sendData.amount)*selected.price):'$0.00'}</span></div><div class="field-error" id="amount-error">Enter an amount greater than zero and within your demo balance.</div></div><div class="review-row"><span>Network</span><strong>${state.network} · Testnet</strong></div><div class="review-row"><span>Estimated network fee</span><strong>0.00042 ETH · ≈ $1.36</strong></div>`;
    if(step===3) body=`<div class="review-row"><span>Asset</span><strong>${selected.name} (${selected.ticker})</strong></div><div class="review-row"><span>Recipient</span><strong>${escapeHtml(shortAddress(state.sendData.recipient))}</strong></div><div class="review-row"><span>Amount</span><strong>${quantity(Number(state.sendData.amount),selected.ticker)} · ${money(Number(state.sendData.amount)*selected.price)}</strong></div><div class="review-row"><span>Network</span><strong>${state.network} · Testnet</strong></div><div class="review-row"><span>Estimated network fee</span><strong>0.00042 ETH · ≈ $1.36</strong></div><div class="review-row review-total"><span>Total</span><strong>${quantity(Number(state.sendData.amount),selected.ticker)}</strong></div><div class="warning-box">${icon('warning')} This only simulates a transaction. No wallet is connected and nothing will be signed or broadcast.</div>`;
    const nextText=step===3?'Simulate transfer':'Continue';
    return `<button class="back-button" data-action="send-back">${icon('back',14)} ${step===0?'Back to wallet':'Previous step'}</button>${demoRibbon()}<div class="flow-layout" style="margin-top:15px"><section class="flow-card surface"><div class="steps">${[0,1,2,3].map(i=>`<span class="step-dot ${step>=i?'active':''}"></span>`).join('')}</div><h2 class="flow-title">${headings[step]}</h2><p class="flow-subtitle">${subtitles[step]}</p>${body}<div class="button-row">${step>0?`<button class="secondary-button" data-action="send-prev">Back</button>`:''}<button class="primary-button" data-action="send-next">${nextText} ${icon('arrow',14)}</button></div></section><aside class="panel surface"><div class="card-heading"><h2 class="card-title">Transfer overview</h2><span class="status pending"><i class="status-dot"></i> Testnet</span></div><div class="data-row"><span>From</span><strong>Nuur Account · ${shortAddress(demoAddress)}</strong></div><div class="data-row"><span>Asset</span><strong>${selected.name}</strong></div><div class="data-row"><span>Available</span><strong>${quantity(selected.amount,selected.ticker)}</strong></div><div class="data-row"><span>Network</span><strong>${state.network}</strong></div><div class="warning-box">${icon('shield')} Always verify the network and recipient address before sending in a real wallet.</div></aside></div>`;
  }
  function renderSendResult() { const tx=state.transaction.tx; const a=assetById(tx.asset); return `<button class="back-button" data-action="send-home">${icon('back',14)} Return to wallet</button>${demoRibbon()}<div class="flow-layout" style="max-width:620px;margin:15px auto"><section class="status-card surface"><div class="success-check">${icon('check',24)}</div><h2>Demo transfer complete</h2><p>Your simulated ${a.ticker} transfer has been added to this session’s activity. No blockchain transaction was created.</p><div class="hash-box">Demo reference<br />${tx.hash}</div><div class="review-row"><span>Amount</span><strong>${quantity(tx.amount,a.ticker)}</strong></div><div class="review-row"><span>To</span><strong>${shortAddress(tx.address)}</strong></div><div class="review-row"><span>Network</span><strong>${tx.network||'Sepolia'} · Testnet</strong></div><div class="button-row"><button class="secondary-button" data-action="goto" data-page="activity">View activity</button><button class="primary-button" data-action="send-home">Done</button></div></section></div>`; }
  function renderSendLoading() { return `<div class="flow-layout" style="max-width:620px;margin:35px auto"><section class="status-card surface"><div class="loading-spinner" role="status" aria-label="Simulating transfer"></div><h2>Preparing demo transfer</h2><p>Updating this session’s sample activity. No wallet signature or network request is being made.</p><span class="status pending"><i class="status-dot"></i> Simulating on ${state.network}</span></section></div>`; }
  function renderReceive() {
    const a=assetById(state.receiveAsset)||assets[0];
    return `${pageHeading('Receive assets', 'Share your public address to receive testnet assets.')}<div class="flow-layout" style="margin-top:16px"><section class="flow-card surface"><h2 class="flow-title">Your receiving address</h2><p class="flow-subtitle">Choose an asset and network. Only share this address with people you trust.</p><div class="field-group"><label class="form-label" for="receive-asset">Asset</label><select id="receive-asset" class="field" data-action="receive-asset-select">${assets.map(x=>`<option value="${x.id}" ${a.id===x.id?'selected':''}>${x.name} (${x.ticker})</option>`).join('')}</select></div><div class="field-group"><label class="form-label" for="receive-network">Network</label><select id="receive-network" class="field" data-action="network-change">${networks.map(n=>`<option ${state.network===n?'selected':''}>${n}</option>`).join('')}</select></div><div class="receive-hero"><div><span class="status pending"><i class="status-dot"></i>${state.network} · Testnet</span><div class="address-box"><span class="address-value">${demoAddress}</span><button class="copy-button" data-action="copy-address">${icon('copy',12)} Copy</button></div><div class="field-hint">This is a fixed demo address. It is not connected to a wallet.</div><div class="button-row"><button class="secondary-button" data-action="share-address">${icon('external',13)} Share address</button></div></div><div class="qr-wrap" aria-label="Illustrative QR code">${qrSvg()}</div></div></section><aside class="panel surface"><div class="card-heading"><h2 class="card-title">Before you receive</h2>${icon('shield',17)}</div><div class="data-row"><span>Asset</span><strong>${a.name}</strong></div><div class="data-row"><span>Network</span><strong>${state.network}</strong></div><div class="data-row"><span>Wallet</span><strong>Demo account</strong></div><div class="warning-box">${icon('warning')} Send only ${a.ticker} on ${state.network}. Wrong-network transfers can be permanently lost in real wallets.</div></aside></div>`;
  }
  function qrSvg() {
    const n=25, cells=[]; let seed=0x71c765;
    const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};
    const finder=(x,y,ox,oy)=>{const dx=x-ox,dy=y-oy;if(dx<0||dx>6||dy<0||dy>6)return null;return dx===0||dx===6||dy===0||dy===6||(dx>=2&&dx<=4&&dy>=2&&dy<=4);};
    const reserved=(x,y)=>[[0,0],[n-7,0],[0,n-7]].some(([ox,oy])=>x>=ox-1&&x<=ox+7&&y>=oy-1&&y<=oy+7);
    for(let y=0;y<n;y++) for(let x=0;x<n;x++) { let f=finder(x,y,0,0);if(f===null)f=finder(x,y,n-7,0);if(f===null)f=finder(x,y,0,n-7);const on= f===null ? (!reserved(x,y)&&rand()>.49) : f;if(on)cells.push(`<rect x="${x}" y="${y}" width="1" height="1"/>`); }
    return `<svg viewBox="-1 -1 27 27" role="img" aria-label="Illustrative QR code, not scannable">${cells.join('')}</svg>`;
  }
  function renderSettings() {
    const settingTabs=[['Profile','user'],['Security','shield'],['Preferences','settings'],['Connected apps','link']];
    let content='';
    if(state.setting==='Profile') content=`<h2>Profile</h2><p>Manage this demo wallet profile and local session.</p><div class="profile-banner" style="padding:14px 0 18px"><div class="avatar">NA</div><div><h2>Nuur Account</h2><p>Demo wallet · ${shortAddress(demoAddress)}</p></div><span class="status pending" style="margin-left:auto">Prototype</span></div><div class="setting-item"><span><span class="setting-title">Wallet address</span><span class="setting-description" style="display:block">Public demo address</span></span><button class="copy-button" data-action="copy-address">${icon('copy',12)} Copy</button></div><div class="setting-item"><span><span class="setting-title">Custody model</span><span class="setting-description" style="display:block">Provider integration not connected</span></span><strong style="font-size:10px">Third-party custody</strong></div><div class="setting-item"><span><span class="setting-title">Session</span><span class="setting-description" style="display:block">Reset returns to onboarding</span></span><button class="danger-button" data-action="reset-demo">Reset demo</button></div>`;
    if(state.setting==='Security') content=`<h2>Security</h2><p>Security controls in this prototype change only the interface state.</p>${toggleSetting('biometric','Biometric unlock','Use Face ID or fingerprint in a production app.')} ${toggleSetting('lock','Auto-lock','Lock the wallet after inactivity.')}<div class="setting-item"><span><span class="setting-title">Auto-lock time</span><span class="setting-description" style="display:block">Applied in a production wallet</span></span><select class="compact-select" data-action="locktime">${['Immediately','1 minute','5 minutes','15 minutes','1 hour'].map(x=>`<option ${state.lockTime===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="warning-box">${icon('shield')} No keys, biometrics, or device security settings are used by this demo.</div>`;
    if(state.setting==='Preferences') content=`<h2>Preferences</h2><p>Choose how information appears in your wallet.</p><div class="setting-item"><span><span class="setting-title">Display currency</span><span class="setting-description" style="display:block">Used for indicative values</span></span><select class="compact-select" data-action="currency">${['USD','EUR','GBP'].map(c=>`<option ${state.currency===c?'selected':''}>${c}</option>`).join('')}</select></div>${toggleSetting('analytics','Usage analytics','Share anonymous product usage data.')}${toggleSetting('offline','Offline preview','Show the offline notice and disable sending.')}<div class="setting-item"><span><span class="setting-title">Network</span><span class="setting-description" style="display:block">All available networks are testnets</span></span><select class="compact-select" data-action="network-change">${networks.map(n=>`<option ${state.network===n?'selected':''}>${n}</option>`).join('')}</select></div><div class="setting-item"><span><span class="setting-title">Appearance</span><span class="setting-description" style="display:block">Premium midnight theme</span></span><strong style="font-size:10px">Dark</strong></div>`;
    if(state.setting==='Connected apps') content=`<h2>Connected applications</h2><p>Review apps that can request wallet access. This prototype has no wallet connections.</p><div class="connection-empty">${icon('link',22)}<br /><strong style="display:inline-block;margin:10px 0 4px;color:var(--text)">No connected apps</strong><br />Connected applications will appear here when you choose to authorize them.</div>`;
    return `${pageHeading('Settings', 'Manage your account, security, and preferences.')}<div class="setting-layout"><nav class="setting-nav surface" aria-label="Settings sections">${settingTabs.map(([t,i])=>`<button class="${state.setting===t?'active':''}" data-action="setting-tab" data-setting="${t}">${icon(i,15)}${t}</button>`).join('')}</nav><section class="setting-section surface">${content}</section></div>`;
  }
  function toggleSetting(key,title,description) { return `<div class="setting-item"><span><span class="setting-title">${title}</span><span class="setting-description" style="display:block">${description}</span></span><button class="toggle ${state.security[key]?'on':''}" data-action="toggle-setting" data-key="${key}" role="switch" aria-checked="${!!state.security[key]}" aria-label="${title}"></button></div>`; }
  function renderTransactionDetail() {
    const tx=state.transactions.find(x=>x.id===state.transaction?.id)||state.transactions[0];
    if(!tx) return `<button class="back-button" data-action="goto" data-page="activity">${icon('back',14)} Back to activity</button><div class="empty-hint">No transaction selected.</div>`;
    const a=assetById(tx.asset);
    return `<button class="back-button" data-action="goto" data-page="activity">${icon('back',14)} Back to activity</button>${demoRibbon()}<div class="flow-layout" style="max-width:880px;margin-top:15px"><section class="panel surface"><div class="card-heading"><h2 class="card-title">Transaction details</h2><span class="status"><i class="status-dot"></i>${tx.status}</span></div><div style="display:grid;place-items:center;padding:10px 0 18px"><span class="activity-symbol ${tx.kind==='sent'?'sent':''}" style="width:48px;height:48px;border-radius:15px">${icon(tx.kind==='sent'?'send':'receive',20)}</span><strong style="margin-top:12px;font-size:12px">${tx.kind==='sent'?'Sent':'Received'} ${a.name}</strong><span style="margin-top:6px;color:var(--muted);font-size:11px">${tx.kind==='sent'?'−':'+'}${quantity(tx.amount,a.ticker)}</span></div><div class="data-row"><span>Status</span><strong><span class="status"><i class="status-dot"></i>${tx.status}</span></strong></div><div class="data-row"><span>Network</span><strong>${tx.network||'Sepolia'} · Testnet</strong></div><div class="data-row"><span>Date</span><strong>${tx.date}</strong></div><div class="data-row"><span>From / To</span><strong>${shortAddress(tx.address)}</strong></div><div class="data-row"><span>Transaction hash</span><strong style="font-family:ui-monospace;font-size:9px">${tx.hash}</strong></div><div class="warning-box">${icon('warning')} This is a simulated activity record. It has no block explorer entry.</div><div class="button-row"><button class="secondary-button" data-action="copy-hash">${icon('copy',13)} Copy reference</button></div></section><section class="panel surface"><div class="card-heading"><h2 class="card-title">Asset details</h2></div><div class="asset-info" style="padding:6px 0 15px">${assetIcon(a)}<span><span class="asset-name">${a.name}</span><span class="asset-ticker">${a.ticker}</span></span></div><div class="data-row"><span>Amount</span><strong>${quantity(tx.amount,a.ticker)}</strong></div><div class="data-row"><span>Estimated value</span><strong>${money(tx.amount*a.price)}</strong></div><button class="secondary-button" style="width:100%;margin-top:17px" data-action="asset-detail" data-asset="${a.id}">View ${a.ticker} asset</button></section></div>`;
  }
  function renderNetwork() { return `${pageHeading('Choose a network', 'Network selection is always explicit before a transfer.')}<div class="panel surface" style="max-width:700px">${networks.map((n,i)=>`<button class="select-asset ${state.network===n?'selected':''}" style="margin-bottom:8px" data-action="choose-network" data-network="${n}"><span class="action-icon" style="color:${i===0?'var(--gold)':i===1?'#8aa8eb':'#b78af0'};background:rgba(255,255,255,.05)">${icon('globe',17)}</span><span class="asset-info"><span><span class="asset-name">${n}</span><span class="asset-ticker">${i===0?'Ethereum':i===1?'Base':'Polygon'} test network</span></span></span><span class="status pending">TESTNET</span>${state.network===n?icon('check',15):icon('chevron',14)}</button>`).join('')}<div class="warning-box" style="margin-top:13px">${icon('warning')} Mainnet networks are intentionally unavailable in this prototype.</div></div>`; }
  function shortAddress(s) { if(!s)return '—'; return s.length>17?`${s.slice(0,6)}...${s.slice(-4)}`:s; }
  function escapeHtml(s='') { return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
  function escapeAttr(s='') { return escapeHtml(s); }
  function bind() {
    document.querySelectorAll('[data-action]').forEach(el=>{
      const action=el.dataset.action;
      if(action==='network-change'||action==='receive-asset-select'||action==='currency'||action==='locktime'||action==='history-network') el.addEventListener('change',onAction);
      else if(el.tagName==='TR'||el.dataset.action==='asset-detail'||el.dataset.action==='transaction-detail') el.addEventListener('click',onAction);
      else el.addEventListener('click',onAction);
    });
    document.querySelectorAll('[data-input]').forEach(el=>el.addEventListener('input',()=>{state.sendData[el.dataset.input]=el.value;if(el.dataset.input==='amount'){const node=document.getElementById('amount-value');if(node)node.textContent=money((Number(el.value)||0)*(assetById(state.asset)?.price||0));const err=document.getElementById('amount-error');if(err)err.classList.remove('show');}if(el.dataset.input==='recipient'){const err=document.getElementById('recipient-error');if(err)err.classList.remove('show');}}));
    document.querySelectorAll('[role="button"], tr[tabindex]').forEach(el=>el.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();el.click();}}));
    const checkbox=document.getElementById('backup-read'); if(checkbox) checkbox.addEventListener('change',()=>{const next=document.getElementById('backup-next');if(next)next.disabled=!checkbox.checked;});
  }
  function onAction(event) {
    const el=event.currentTarget, action=el.dataset.action, page=el.dataset.page;
    if(action==='onboard'){state.onboarding=el.dataset.step;render();}
    else if(action==='enter-demo'){state.ready=true;state.page='home';render();}
    else if(action==='finish-onboarding'){state.ready=true;state.page='home';render();toast('Your demo wallet is ready');}
    else if(action==='goto'){if(page==='send'&&state.security.offline){toast('Sending is unavailable in offline mode');return;}state.page=page;state.transaction=null;if(page==='send'){state.sendStep=0;state.transaction=null;state.sendData={recipient:'',amount:''};}render();}
    else if(action==='toggle-balance'){state.hideBalance=!state.hideBalance;render();}
    else if(action==='asset-detail'){state.asset=el.dataset.asset;state.page='assetDetail';render();}
    else if(action==='receive-asset'){state.receiveAsset=el.dataset.asset;state.page='receive';render();}
    else if(action==='select-send-asset'){state.asset=el.dataset.asset;render();}
    else if(action==='transaction-detail'){state.transaction={id:el.dataset.tx};state.page='transactionDetail';render();}
    else if(action==='history-filter'){state.historyFilter=el.dataset.filter;render();}
    else if(action==='history-network'){state.historyNetwork=el.value;render();}
    else if(action==='receive-asset-select'){state.receiveAsset=el.value;render();}
    else if(action==='network-change'){state.network=el.value;render();}
    else if(action==='choose-network'){state.network=el.dataset.network;state.page='assets';render();toast(`Network set to ${state.network}`);}
    else if(action==='setting-tab'){state.setting=el.dataset.setting;render();}
    else if(action==='toggle-setting'){const key=el.dataset.key;state.security[key]=!state.security[key];render();}
    else if(action==='currency'){state.currency=el.value;render();toast(`Display currency set to ${state.currency}`);}
    else if(action==='locktime'){state.lockTime=el.value;render();}
    else if(action==='max-amount'){const a=assetById(state.asset);const max=a.id==='eth'?Math.max(0,a.amount-.00042):a.amount;state.sendData.amount=String(Number(max.toFixed(6)));render();}
    else if(action==='send-back'){if(state.sendStep>0){state.sendStep--;render();}else{state.page='home';render();}}
    else if(action==='send-prev'){state.sendStep=Math.max(0,state.sendStep-1);render();}
    else if(action==='send-next'){advanceSend();}
    else if(action==='send-home'){state.page='home';state.transaction=null;state.sendStep=0;state.sendData={recipient:'',amount:''};render();}
    else if(action==='copy-address'){copyText(demoAddress,'Demo address copied');}
    else if(action==='copy-hash'){copyText(state.transaction?.tx?.hash||'Simulated transaction reference','Demo reference copied');}
    else if(action==='share-address'){if(navigator.share)navigator.share({title:'NUUR Wallet demo address',text:`${demoAddress} (${state.network} testnet)`}).catch(()=>{});else copyText(demoAddress,'Address copied for sharing');}
    else if(action==='export-history'){toast('Export is not available in this prototype');}
    else if(action==='reset-demo'){state.ready=false;state.onboarding='welcome';state.page='home';state.transactions=initialTransactions.slice();state.transaction=null;assets=seedAssets.map(asset=>({...asset}));state.security={biometric:true,lock:true,analytics:false,offline:false};state.currency='USD';state.network='Sepolia';render();}
    else if(action==='notify'){toast('You’re all caught up');}
    else if(action==='range'){document.querySelectorAll('.range-button').forEach(b=>b.classList.toggle('active',b===el));}
  }
  function advanceSend() {
    if(state.sendStep===0){state.sendStep=1;render();return;}
    if(state.sendStep===1){const input=document.getElementById('recipient');const val=input?.value.trim()||'';state.sendData.recipient=val; if(!/^0x[a-fA-F0-9]{40}$/.test(val)){document.getElementById('recipient-error')?.classList.add('show');return;}state.sendStep=2;render();return;}
    if(state.sendStep===2){const input=document.getElementById('amount');const amount=Number(input?.value);state.sendData.amount=input?.value||'';const a=assetById(state.asset);if(!Number.isFinite(amount)||amount<=0||amount>a.amount){document.getElementById('amount-error')?.classList.add('show');return;}if(a.id==='eth'&&amount>a.amount-.00042){document.getElementById('amount-error').textContent='Leave enough ETH to cover the estimated demo network fee.';document.getElementById('amount-error')?.classList.add('show');return;}if(a.id!=='eth'&&assets.find(item=>item.id==='eth').amount<.00042){document.getElementById('amount-error').textContent='Your demo wallet needs ETH available for the estimated network fee.';document.getElementById('amount-error')?.classList.add('show');return;}state.sendStep=3;render();return;}
    if(state.sendStep===3){const a=assetById(state.asset),amount=Number(state.sendData.amount),fee=.00042;const tx={id:`demo-${Date.now()}`,kind:'sent',asset:a.id,amount,date:'Just now',status:'Pending',hash:`demo-${Math.random().toString(16).slice(2,10)}-${Date.now().toString(16)}`,address:state.sendData.recipient,network:state.network,demo:true};a.amount-=amount;if(a.id!=='eth')assets.find(item=>item.id==='eth').amount=Math.max(0,assets.find(item=>item.id==='eth').amount-fee);else a.amount=Math.max(0,a.amount-fee);state.transactions.unshift(tx);state.transaction={mode:'loading',tx};render();setTimeout(()=>{tx.status='Confirmed';if(state.transaction?.tx===tx)state.transaction={mode:'send',tx};if(state.ready)render();},850);}
  }
  async function copyText(text,message) { try{await navigator.clipboard.writeText(text);toast(message);}catch{const area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.opacity='0';document.body.appendChild(area);area.select();try{document.execCommand('copy');toast(message);}catch{toast('Copy is unavailable in this browser');}area.remove();} }
  function toast(message) { const root=document.getElementById('toast-root');if(!root)return;root.innerHTML=`<div class="toast">${icon('check',15)}${escapeHtml(message)}</div>`;clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>{const t=document.querySelector('.toast');if(t)t.remove();},2600); }
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.ready){state.page='home';state.transaction=null;render();}});
  render();
})();
